#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: HUM-002 owner-controlled Arbitrum Sepolia test assets.
# --------------------------------------------------------------------------

TOTAL_STAGES=5
ENV_FILE="${HUM002_ENV_FILE:-contracts/.env}"
RPC_URL="https://sepolia-rollup.arbitrum.io/rpc"
CHAIN_ID_EXPECTED="421614"
USDC_ADDRESS="0x75faf114eafb1BDbe2F0316DF893fd58CE46AA4d"
MIN_AI_USER_USDC="50000"

read_public_value() {
  local key="$1" value
  value=$(awk -F= -v key="$key" '$1 == key { sub(/^[^=]*=/, ""); print; exit }' "$ENV_FILE")
  [[ -n "$value" ]] || { warn "Missing $key in $ENV_FILE. Complete HUM-001 first."; exit 1; }
  printf '%s' "$value"
}

require_uint() {
  [[ "$2" =~ ^[0-9]+$ ]] || { warn "$1 did not return an integer."; exit 1; }
}

require_positive() {
  require_uint "$1" "$2"
  (( $2 > 0 )) || { warn "$1 has a zero balance."; exit 1; }
}

banner "Nebula HUM-002 testnet asset provisioning"

stage "Network and identity preflight"
say "This wizard uses public addresses and read-only RPC calls. It never requests a key or signs a transaction."
[[ -f "$ENV_FILE" ]] || { warn "$ENV_FILE is missing. Complete HUM-001 first."; exit 1; }
git check-ignore -q "$ENV_FILE" || { warn "$ENV_FILE is not Git-ignored."; exit 1; }
command -v cast >/dev/null 2>&1 || { warn "Foundry cast is required."; exit 1; }
DEPLOYER=$(read_public_value HUM001_DEPLOYER_ADDRESS)
VERIFIER=$(read_public_value NEBULA_BACKEND_VERIFIER)
AI_USER=$(read_public_value HUM001_AI_USER_ADDRESS)
PROVIDER=$(read_public_value HUM001_PROVIDER_ADDRESS)
WORKER=$(read_public_value HUM001_WORKER_SIGNER_ADDRESS)
chain_id=$(cast chain-id --rpc-url "$RPC_URL")
[[ "$chain_id" == "$CHAIN_ID_EXPECTED" ]] || { warn "RPC returned chain ID $chain_id, expected $CHAIN_ID_EXPECTED."; exit 1; }
usdc_code=$(cast code "$USDC_ADDRESS" --rpc-url "$RPC_URL")
[[ "$usdc_code" != "0x" ]] || { warn "Circle USDC address has no contract code."; exit 1; }
usdc_decimals=$(cast call "$USDC_ADDRESS" "decimals()(uint8)" --rpc-url "$RPC_URL" | awk '{print $1}')
[[ "$usdc_decimals" == "6" ]] || { warn "Circle USDC decimals are $usdc_decimals, expected 6."; exit 1; }
say "Verified Arbitrum Sepolia chain ID, Circle USDC code, and six decimals."

stage "Fund the deployer and contract owner"
open_url "https://docs.arbitrum.io/for-devs/dev-tools-and-resources/chain-info#faucet-list"
step "Use only a faucet linked from the official Arbitrum faucet list."
step "Select Arbitrum Sepolia, never Arbitrum One or another mainnet."
step "Request test ETH for the deployer/owner public address shown below."
say "Deployer/owner: $DEPLOYER"
warn "Testnet ETH has no financial value. Never enter a seed phrase or private key into a faucet."
pause "Press Enter only after the wallet shows Arbitrum Sepolia ETH."

stage "Fund runtime gas roles"
step "Request Arbitrum Sepolia ETH for the backend verifier."
say "Backend verifier: $VERIFIER"
step "Request Arbitrum Sepolia ETH for the AI user."
say "AI user: $AI_USER"
step "Request Arbitrum Sepolia ETH for the provider payout wallet."
say "Provider payout: $PROVIDER"
warn "Do not fund the worker signer. It signs EIP-712 envelopes off-chain and must remain unfunded."
say "Worker signer that must stay unfunded: $WORKER"
pause "Press Enter after the verifier, AI user, and provider show test ETH."

stage "Fund the AI user with Circle test USDC"
open_url "https://faucet.circle.com/"
step "Select USDC."
step "Select Arbitrum Sepolia."
step "Paste only the AI-user public address shown below."
say "AI user: $AI_USER"
step "Complete the CAPTCHA and request the current test-USDC distribution."
warn "Confirm the network says Arbitrum Sepolia before submitting."
pause "Press Enter after Circle reports success or the USDC balance appears."

stage "Verify balances and record evidence"
DEPLOYER_ETH_WEI=$(cast balance "$DEPLOYER" --rpc-url "$RPC_URL")
VERIFIER_ETH_WEI=$(cast balance "$VERIFIER" --rpc-url "$RPC_URL")
AI_USER_ETH_WEI=$(cast balance "$AI_USER" --rpc-url "$RPC_URL")
PROVIDER_ETH_WEI=$(cast balance "$PROVIDER" --rpc-url "$RPC_URL")
WORKER_ETH_WEI=$(cast balance "$WORKER" --rpc-url "$RPC_URL")
AI_USER_USDC_BASE_UNITS=$(cast call "$USDC_ADDRESS" "balanceOf(address)(uint256)" "$AI_USER" --rpc-url "$RPC_URL" | awk '{print $1}')
require_positive "deployer/owner ETH" "$DEPLOYER_ETH_WEI"
require_positive "backend verifier ETH" "$VERIFIER_ETH_WEI"
require_positive "AI-user ETH" "$AI_USER_ETH_WEI"
require_positive "provider ETH" "$PROVIDER_ETH_WEI"
require_uint "worker-signer ETH" "$WORKER_ETH_WEI"
(( WORKER_ETH_WEI == 0 )) || { warn "Worker signer is funded; HUM-002 requires it to remain unfunded."; exit 1; }
require_uint "AI-user USDC" "$AI_USER_USDC_BASE_UNITS"
(( AI_USER_USDC_BASE_UNITS >= MIN_AI_USER_USDC )) || {
  warn "AI-user USDC is below 50,000 base units (0.05 test USDC)."
  exit 1
}
say "All required gas roles have nonzero test ETH."
say "The AI user has at least 0.05 test USDC; NET-001 must recheck against the final approved price."
say "The worker signer remains unfunded."
confirm "Approve these read-only balances as HUM-002 evidence?" || {
  warn "Balance evidence not approved; nothing was written."
  exit 1
}
write_env NEBULA_USDC "$USDC_ADDRESS"
write_env HUM002_CHAIN_ID "$CHAIN_ID_EXPECTED"
write_env HUM002_DEPLOYER_ETH_WEI "$DEPLOYER_ETH_WEI"
write_env HUM002_VERIFIER_ETH_WEI "$VERIFIER_ETH_WEI"
write_env HUM002_AI_USER_ETH_WEI "$AI_USER_ETH_WEI"
write_env HUM002_PROVIDER_ETH_WEI "$PROVIDER_ETH_WEI"
write_env HUM002_WORKER_ETH_WEI "$WORKER_ETH_WEI"
write_env HUM002_AI_USER_USDC_BASE_UNITS "$AI_USER_USDC_BASE_UNITS"
write_env HUM002_VERIFIED_AT_UTC "$(date -u +%Y-%m-%dT%H:%M:%SZ)"
write_env HUM002_OWNER_APPROVED true
chmod 600 "$ENV_FILE"
say "Recorded only public balance evidence in $ENV_FILE. No project deployment was performed."
finish
